(8,'Comunicado de Prueba','Lorem Ipsum is simply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry\'s standard dummy text ever since the 1500s.',0,'2026-02-15 12:07:05','2026-02-15 12:07:05',0,NULL,55,3),
(10,'Nuevo comunicado 666','Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 Nuevo comunicado 666 ',0,'2026-02-15 15:02:53','2026-04-29 08:43:38',1,'2026-04-29 08:43:38',55,3),
