INSERT INTO `mensaje` VALUES
(1,'Buenas, profe. Una duda sobre el examen del próximo lunes: ¿entra el tema 5 entero?','2026-04-22 17:30:00',1,57,50),
(2,'i0vpHKfGGF7vV4xWI0gwJ0hzekN1UXBoQXNFSElVUE5WMnJISEVkN0hMcE5ESWxxUmZsWGJsWHcyeGN6ck1DbWFMQllFTjUxOWFSUFpDalFCeStqQjNXeFd6bnlxREJ5aWFPUzB2a3pCczF2UHd5ZThBVzZxQXRWY2lDMlhEWkdiL1RXNllLR25HK2lCbWFo','2026-04-22 19:00:00',1,50,57),
(3,'Perfecto, gracias.','2026-04-22 19:15:00',1,57,50),
(4,'Profe, no he podido subir la entrega a tiempo por un problema con el wifi de casa. ¿Puedo enviarla esta noche?','2026-04-25 14:20:00',1,64,53),
(5,'Está bien, hasta mañana 9:00 acepto la entrega. Indícalo en el comentario.','2026-04-25 18:05:00',0,53,64),
(6,'Hola, ¿podría revisar la nota del último ejercicio? Creo que falta una parte.','2026-04-26 11:10:00',0,67,51),
(7,'Te lo reviso esta tarde y te confirmo.','2026-04-26 11:45:00',1,51,67),
(8,'Confirmado, había un fallo en la corrección. Te lo subo a 7.0.','2026-04-26 19:20:00',1,51,67),
(9,'¡Muchas gracias!','2026-04-26 19:25:00',0,67,51),
(10,'Alberto, recordatorio: las notas de la 2ª evaluación deben estar cerradas antes del jueves 30/04.','2026-04-27 09:00:00',1,55,50),
(11,'Perfecto, las cierro mañana mismo. Solo me quedan 2 alumnos por evaluar.','2026-04-27 09:30:00',1,50,55),
(12,'Walter, ¿puedes pasarte por dirección esta tarde? Tema horarios de la 3ª evaluación.','2026-04-28 10:00:00',1,55,53),
(13,'mcaDHkuucTkt6qMBcKVU+VZEc1RFM3k0U3l1b3hEajQrZ2NDYU45RkxMbUZzRkFKSSt1OExZbEcxMzFDby9pbmtzWURVK1VHbWNrK2xXVW0=','2026-04-28 10:05:00',1,53,55),
(14,'Profe, no he encontrado el material del tema 3 en la plataforma.','2026-04-23 16:00:00',1,60,52),
(15,'Lo acabo de subir, refresca la página de Programación.','2026-04-23 16:30:00',0,52,60),
(16,'Buenas, profe Alberto. ¿La recuperación de la 2ª eval cuándo sería?','2026-04-28 18:00:00',1,72,50),
(17,'Hola Aaron. Está prevista para el 8 de junio. Lo confirmo en el comunicado de centro.','2026-04-28 18:25:00',1,50,72);
